            "isRequired": true,
            "order": 3,
            "options": [
                {
                    "value": "React",
                    "order": 1
                },
                {
                    "value": "Vue",
                    "order": 2
                },
                {
                    "value": "Angular",
                    "order": 3
                }
            ]
        },
        {
